import type { Span, TransactionSource } from '@sentry/core';
import { debug, getActiveSpan, getRootSpan, spanToJSON } from '@sentry/core';
import { DEBUG_BUILD } from '../debug-build';
import type { Location, MatchRoutes, ReactRouterConfig, RouteMatch, RouteObject } from '../types';
import { matchRouteManifest, stripBasenameFromPathname } from './route-manifest';
import { SENTRY_OP } from '@sentry/conventions/attributes';

// Navigation context stack for nested/concurrent patchRoutesOnNavigation calls.
// Required because window.location hasn't updated yet when handlers are invoked.
interface NavigationContext {
  token: object;
  targetPath: string | undefined;
  span: Span | undefined;
}

const _navigationContextStack: NavigationContext[] = [];
const MAX_CONTEXT_STACK_SIZE = 10;

/**
 * Pushes a navigation context and returns a unique token for cleanup.
 * The token uses object identity for uniqueness (no counter needed).
 */
export function setNavigationContext(targetPath: string | undefined, span: Span | undefined): object {
  const token = {};
  // Prevent unbounded stack growth - oldest (likely stale) contexts are evicted first
  if (_navigationContextStack.length >= MAX_CONTEXT_STACK_SIZE) {
    DEBUG_BUILD && debug.warn('[React Router] Navigation context stack overflow - removing oldest context');
    _navigationContextStack.shift();
  }
  _navigationContextStack.push({ token, targetPath, span });
  return token;
}

/**
 * Clears the navigation context if it's on top of the stack (LIFO).
 * If our context is not on top (out-of-order completion), we leave it -
 * it will be cleaned up by overflow protection when the stack fills up.
 */
export function clearNavigationContext(token: object): void {
  const top = _navigationContextStack[_navigationContextStack.length - 1];
  if (top?.token === token) {
    _navigationContextStack.pop();
  }
}

/** Gets the current (most recent) navigation context if inside a patchRoutesOnNavigation call. */
export function getNavigationContext(): NavigationContext | null {
  const length = _navigationContextStack.length;
  // The `?? null` converts undefined (from array access) to null to match return type
  return length > 0 ? (_navigationContextStack[length - 1] ?? null) : null;
}

// Helper functions
function pickPath(match: RouteMatch): string {
  return trimWildcard(match.route.path || '');
}

function pickSplat(match: RouteMatch): string {
  return match.params['*'] || '';
}

function trimWildcard(path: string): string {
  return path[path.length - 1] === '*' ? path.slice(0, -1) : path;
}

function trimSlash(path: string): string {
  return path[path.length - 1] === '/' ? path.slice(0, -1) : path;
}

/**
 * Checks if a path ends with a wildcard character (*).
 */
export function pathEndsWithWildcard(path: string): boolean {
  return path.endsWith('*');
}

/** Checks if transaction name has wildcard (/* or ends with *). */
export function transactionNameHasWildcard(name: string): boolean {
  return name.includes('/*') || name.endsWith('*');
}

/**
 * Checks if a path is a wildcard and has child routes.
 */
export function pathIsWildcardAndHasChildren(path: string, branch: RouteMatch<string>): boolean {
  return (pathEndsWithWildcard(path) && !!branch.route.children?.length) || false;
}

/** Check if route is in descendant route (<Routes> within <Routes>) */
export function routeIsDescendant(route: RouteObject): boolean {
  return !!(!route.children && route.element && route.path?.endsWith('/*'));
}

function sendIndexPath(
  pathBuilder: string,
  pathname: string,
  basename: string,
  stripBasename: boolean,
): [string, TransactionSource] {
  const reconstructedPath =
    pathBuilder && pathBuilder.length > 0
      ? pathBuilder
      : stripBasename
        ? stripBasenameFromPathname(pathname, basename)
        : pathname;

  let formattedPath =
    // If the path ends with a wildcard suffix, remove both the slash and the asterisk
    reconstructedPath.slice(-2) === '/*' ? reconstructedPath.slice(0, -2) : reconstructedPath;

  // If the path ends with a slash, remove it (but keep single '/')
  if (formattedPath.length > 1 && formattedPath[formattedPath.length - 1] === '/') {
    formattedPath = formattedPath.slice(0, -1);
  }

  return [formattedPath, 'route'];
}

/**
 * Returns the number of URL segments in the given URL string.
 * Splits at '/' or '\/' to handle regex URLs correctly.
 *
 * @param url - The URL string to segment.
 * @returns The number of segments in the URL.
 */
export function getNumberOfUrlSegments(url: string): number {
  // split at '/' or at '\/' to split regex urls correctly
  return url.split(/\\?\//).filter(s => s.length > 0 && s !== ',').length;
}

// Exported utility functions

/**
 * Ensures a path string starts with a forward slash.
 */
export function prefixWithSlash(path: string): string {
  return path[0] === '/' ? path : `/${path}`;
}

/**
 * Removes as many leading segments from `pathname` as `pathnameBase` has, the way `useRoutes` strips the parent
 * `pathnameBase` for descendant routes.
 *
 * `location.pathname` is percent-encoded as the browser holds it, while React Router decodes the pathname before
 * matching, so `pathnameBase` on a `RouteMatch` is decoded (older 6.x routers decoded only partially, or not at all).
 * Stripping by segment count works regardless of which side is encoded, and keeps the remainder encoded so that
 * matching it again decodes it exactly once.
 */
function stripPathnameBaseSegments(pathname: string, pathnameBase: string): string {
  const baseSegmentCount = countPathnameSegments(pathnameBase);
  if (baseSegmentCount === 0) {
    return pathname;
  }
  return prefixWithSlash(pathname.split('/').filter(Boolean).slice(baseSegmentCount).join('/'));
}

/**
 * Counts the segments of a pathname with a plain split (`getNumberOfUrlSegments` also drops `,` segments, which a
 * route parameter can legitimately be).
 */
function countPathnameSegments(pathname: string): number {
  return pathname.split('/').filter(Boolean).length;
}

/**
 * Rebuilds the route path from all available routes by matching against the current location.
 */
export function rebuildRoutePathFromAllRoutes(
  allRoutes: RouteObject[],
  location: Location,
  matchRoutes: MatchRoutes,
): string {
  const matchedRoutes = matchRoutes(allRoutes, location) as RouteMatch[];

  if (!matchedRoutes || matchedRoutes.length === 0) {
    return '';
  }

  for (const match of matchedRoutes) {
    if (match.route.path && match.route.path !== '*') {
      const path = pickPath(match);
      const strippedPath = stripPathnameBaseSegments(location.pathname, prefixWithSlash(match.pathnameBase));

      if (location.pathname === strippedPath) {
        return trimSlash(strippedPath);
      }

      return trimSlash(
        trimSlash(path || '') +
          prefixWithSlash(
            rebuildRoutePathFromAllRoutes(
              allRoutes.filter(route => route !== match.route),
              {
                pathname: strippedPath,
              },
              matchRoutes,
            ),
          ),
      );
    }
  }

  return '';
}

/**
 * Recovers the parent prefix for descendant `<Routes>` names.
 *
 * `allRoutes` flattens every mounted `<Routes>` into one set, so an orphaned descendant subtree can
 * outscore the `.../*` route that anchors the location and drop its prefix (e.g. `/:id/:sub` instead of `/child/:id`).
 * Matching only the descendant-parent routes recovers the true anchor.
 */
function reconstructNameFromDescendantParent(
  location: Location,
  allRoutes: RouteObject[],
  currentName: string | undefined,
  matchRoutes: MatchRoutes,
): string | undefined {
  const descendantParents = allRoutes.filter(routeIsDescendant);
  if (!descendantParents.length) {
    return undefined;
  }

  const matchedParents = matchRoutes(descendantParents, location) as RouteMatch[] | null;
  const parentMatch = matchedParents?.[matchedParents.length - 1];
  if (!parentMatch || !pickSplat(parentMatch)) {
    return undefined;
  }

  const parentTemplate = trimSlash(trimWildcard(parentMatch.route.path || ''));

  if (!parentTemplate) {
    return undefined;
  }

  const expectedPrefix = prefixWithSlash(parentTemplate);

  // Child `<Routes>` resolve against the matched parent, but flattened route matching can already retain
  // a dynamic leading parameter. Adding the parent again would duplicate it (e.g. `/:id/:id`)
  const firstElement = parentTemplate.split('/')[0];
  const hasDynamicLead = firstElement?.startsWith(':') && currentName?.split('/').includes(firstElement);

  // Rebuild only when matching the descendant subtree discarded its parent route template
  if (currentName === expectedPrefix || currentName?.startsWith(`${expectedPrefix}/`) || hasDynamicLead) {
    return undefined;
  }

  const remainingPathname = stripPathnameBaseSegments(location.pathname, prefixWithSlash(parentMatch.pathnameBase));
  const remainingName = rebuildRoutePathFromAllRoutes(
    allRoutes.filter(route => route !== parentMatch.route),
    { pathname: remainingPathname },
    matchRoutes,
  );

  return remainingName ? prefixWithSlash(`${parentTemplate}${prefixWithSlash(remainingName)}`) : undefined;
}

/**
 * Returns the routes that aren't a child of another route in the list.
 * `matchRoutes` already walks each route's children, so also passing those children multiplies its work.
 */
export function getRootRoutes(routes: RouteObject[]): RouteObject[] {
  const nestedRoutes = new Set(routes.flatMap(route => route.children ?? []));
  return routes.filter(route => !nestedRoutes.has(route));
}

/**
 * Checks if the current location is inside a descendant route (route with splat parameter).
 */
export function locationIsInsideDescendantRoute(
  location: Location,
  routes: RouteObject[],
  matchRoutes: MatchRoutes,
): boolean {
  return matchesAreInsideDescendantRoute(matchRoutes(getRootRoutes(routes), location) as RouteMatch[] | null);
}

function matchesAreInsideDescendantRoute(matches: RouteMatch[] | null): boolean {
  return !!matches?.some(match => routeIsDescendant(match.route) && pickSplat(match));
}

/**
 * Returns a fallback transaction name from location pathname.
 */
function getFallbackTransactionName(location: Location, basename: string, stripBasename: boolean): string {
  return stripBasename ? stripBasenameFromPathname(location.pathname, basename) : location.pathname || '';
}

/**
 * Gets a normalized route name and transaction source from the current routes and location.
 */
export function getNormalizedName(
  routes: RouteObject[],
  location: Location,
  branches: RouteMatch[],
  basename: string = '',
  stripBasename: boolean = false,
): [string, TransactionSource] {
  if (!routes || routes.length === 0) {
    return [stripBasename ? stripBasenameFromPathname(location.pathname, basename) : location.pathname, 'url'];
  }

  if (!branches) {
    return [getFallbackTransactionName(location, basename, stripBasename), 'url'];
  }

  let pathBuilder = '';

  for (const branch of branches) {
    const route = branch.route;
    if (!route) {
      continue;
    }

    // Early return for index routes
    if (route.index) {
      return sendIndexPath(pathBuilder, branch.pathname, basename, stripBasename);
    }

    const path = route.path;
    if (!path || pathIsWildcardAndHasChildren(path, branch)) {
      continue;
    }

    // Build the route path
    const newPath = path[0] === '/' || pathBuilder[pathBuilder.length - 1] === '/' ? path : `/${path}`;
    pathBuilder = trimSlash(pathBuilder) + prefixWithSlash(newPath);

    // Check if this branch spans the whole location. Compare segment counts rather than strings: the location
    // pathname is percent-encoded while React Router decoded the branch pathname, and decoding never changes the
    // number of segments.
    if (countPathnameSegments(location.pathname) !== countPathnameSegments(basename + branch.pathname)) {
      continue;
    }

    // Check if this is a parameterized route like /stores/:storeId/products/:productId
    if (
      getNumberOfUrlSegments(pathBuilder) !== getNumberOfUrlSegments(branch.pathname) &&
      !pathEndsWithWildcard(pathBuilder)
    ) {
      return [(stripBasename ? '' : trimSlash(basename)) + newPath, 'route'];
    }

    // Handle wildcard routes with children - strip trailing wildcard
    if (pathIsWildcardAndHasChildren(pathBuilder, branch)) {
      pathBuilder = pathBuilder.slice(0, -1);
    }

    return [(stripBasename ? '' : trimSlash(basename)) + pathBuilder, 'route'];
  }

  // Fallback when no matching route found
  return [getFallbackTransactionName(location, basename, stripBasename), 'url'];
}

/**
 * Shared helper function to resolve route name and source
 */
export function resolveRouteNameAndSource(
  location: Location,
  routes: RouteObject[],
  allRoutes: RouteObject[],
  branches: RouteMatch[],
  config: ReactRouterConfig,
): [string, TransactionSource] {
  const { matchRoutes, stripBasename, basename, lazyRouteManifest, enableAsyncRouteHandlers } = config;

  // When lazy route manifest is provided, use it as the primary source for transaction names
  if (enableAsyncRouteHandlers && lazyRouteManifest && lazyRouteManifest.length > 0) {
    const manifestMatch = matchRouteManifest(location.pathname, lazyRouteManifest, basename);
    if (manifestMatch) {
      return [(stripBasename ? '' : trimSlash(basename)) + manifestMatch, 'route'];
    }
  }

  // Fall back to React Router route matching
  let name: string | undefined;
  let source: TransactionSource = 'url';

  // `branches` were matched with the basename, which the descendant route lookups don't strip.
  const isInDescendantRoute = basename
    ? locationIsInsideDescendantRoute(location, allRoutes, matchRoutes)
    : matchesAreInsideDescendantRoute(branches);

  if (isInDescendantRoute) {
    name = prefixWithSlash(rebuildRoutePathFromAllRoutes(allRoutes, location, matchRoutes));
    source = 'route';
  }

  if (!isInDescendantRoute || !name) {
    [name, source] = getNormalizedName(routes, location, branches, basename, stripBasename);
  }

  // Guard against orphaned descendant subtrees stealing the transaction name: if the location is
  // anchored by a descendant-parent route (`.../*`) whose prefix was dropped, reconstruct with it.
  const anchoredName = reconstructNameFromDescendantParent(location, allRoutes, name, matchRoutes);
  if (anchoredName) {
    return [anchoredName, 'route'];
  }

  return [name || location.pathname, source];
}

/**
 * Gets the active root span if it's a pageload or navigation span.
 */
export function getActiveRootSpan(): Span | undefined {
  const span = getActiveSpan();
  const rootSpan = span ? getRootSpan(span) : undefined;

  if (!rootSpan) {
    return undefined;
  }

  const op = spanToJSON(rootSpan).attributes[SENTRY_OP];

  // Only use this root span if it is a pageload or navigation span
  return op === 'navigation' || op === 'pageload' ? rootSpan : undefined;
}
